import sys
sys.setrecursionlimit(10**7)

mod = 998244353

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    m = int(input[1])
    p = int(input[2])
    q = int(input[3])
    segmentLength = q - p + 1
    if p % 2 == 0:
        segmentLength -= segmentLength // 2
    else:
        segmentLength //= 2
    otherSegment = (q - p + 1) - segmentLength
    memo = [{}, {}]
    if ((n & m) % 2) == 0:
        answer = recursiveFn(segmentLength, otherSegment, n * m, 0, memo)
        print(answer)
    else:
        answer = binomial(segmentLength + otherSegment, n * m)
        print(answer)

def recursiveFn(x, y, total, type_, memo):
    if total in memo[type_]:
        return memo[type_][total]
    if total == 1:
        return x if type_ == 0 else y
    if total % 2 == 1:
        res = (x * recursiveFn(x, y, total - 1, type_, memo) + y * recursiveFn(x, y, total - 1, (type_ + 1) % 2, memo)) % mod
        return res
    else:
        half = total // 2
        ch = recursiveFn(x, y, half, 0, memo)
        nch = recursiveFn(x, y, half, 1, memo)
        if type_ == 0:
            ans = (ch * ch + nch * nch) % mod
        else:
            ans = (2 * ch * nch) % mod
        memo[type_][total] = ans
        return ans

def binomial(x, st):
    if st == 0:
        return 1
    if st == 1:
        return x
    half = st // 2
    res = binomial(x, half)
    if st % 2 == 0:
        return (res * res) % mod
    else:
        return (((res * res) % mod) * x) % mod

if __name__ == "__main__":
    main()

